INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15339, 0, 0, 'koKR', 'Moje siły odżyły!'),
(15339, 0, 1, 'koKR', 'Moje moce się odnowiły!'),
(15339, 0, 2, 'koKR', 'Moje moce powracają!'),
(15339, 1, 0, 'koKR', 'Brońcie miasta za wszelką cenę!'),
(15339, 1, 1, 'koKR', 'Na stanowiska. Brońcie miasta.'),
(15339, 1, 2, 'koKR', 'Intruzi zostaną zlikwidowani.'),
(15341, 6, 0, 'koKR', 'Atakujcie i niech drogo za to zapłacą!'),
(15341, 7, 0, 'koKR', 'Zmiażdżcie ich! Wypędźcie ich!'),
(15341, 8, 0, 'koKR', 'Nie wahajcie się! Zniszczcie ich!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(11018, 'koKR', '%s kontratakuje w odwecie.', '', 0),
(11067, 'koKR', 'Nie jesteś $gwart:warta; mojego czasu, $n!', '', 0),
(11074, 'koKR', '%s upatruje sobie $n!', '', 0),
(11429, 'koKR', 'Wkrótce poznacie cenę swojego wtrącania się, śmiertelnicy... Mistrz jest już niemal cały... A gdy powstanie, wasz świat przestanie istnieć.', '', 0),
(11433, 'koKR', 'Wydaj ostatnie tchnienie!', '', 0),
(11434, 'koKR', 'Wojownicy, kapitanowie, walczcie dalej!', '', 0),
(11435, 'koKR', 'Bezczelny głupcze! Sam cię zabiję!', '', 0),
(11436, 'koKR', 'Fandralu! Nadszedł twój czas! Idź i ukryj się w Szmaragdowym Śnie, i módl się, żebyśmy cię nigdy nie znaleźli!\n', '', 0),
(11437, 'koKR', 'Jeleniorogi będzie skomlał i błagał o życie, tak jak ten szczeniak, jego syn! Tysiąc lat niesprawiedliwości skończy się dzisiaj!\n', '', 0),
(11438, 'koKR', 'Strach jest dla wroga! Strach i śmierć!', '', 0),
(11439, 'koKR', 'Nie będziemy już dłużej czekać za zaryglowanymi drzwiami i kamiennymi murami! Nikt już nie odmówi nam zemsty! Same smoki zadrżą przed naszym gniewem!\n', '', 0),
(11440, 'koKR', 'Nadchodzi czas naszej odpłaty! Niech ciemność zapanuje w sercach naszych wrogów!', '', 0),
(11441, 'koKR', '%s wyczuwa twój strach.', '', 0),
(11449, 'koKR', 'Piaski pustyni, powstańcie i przesłońcie słońce!', '', 0),
(11450, 'koKR', 'Zostajesz $gzlikwidowany:zlikwidowana;.', '', 0),
(11451, 'koKR', 'To... moja... porażka.', '', 0),
(11474, 'koKR', '%s wysysa twoją manę i zamienia się w kamień.', '', 0),
(11720, 'koKR', 'Mury zostały przełamane!', '', 0),
(12781, 'koKR', '%s aż iskrzy od energii!', '', 0);
